var e=(e=>document.getElementById(e));chrome.storage.local.get(`md_config`).then(t=>{let{md_config:n}=t;n?.server&&(e(`server`).value=n.server)}),e(`pairBtn`).onclick=async()=>{let t=e(`server`).value.trim().replace(/\/+$/,``),n=e(`code`).value.trim(),r=e(`pairMsg`);if(!/^https?:\/\//.test(t)){r.className=`msg err`,r.textContent=`服务器地址需以 http(s):// 开头`;return}if(!/^\d{6}$/.test(n)){r.className=`msg err`,r.textContent=`配对码为 6 位数字`;return}try{let e=new URL(t).origin+`/*`;if(!await chrome.permissions.request({origins:[e]})){r.className=`msg err`,r.textContent=`未授予该站点的访问权限`;return}}catch{}r.className=`msg`,r.textContent=`配对中…`;let i=await chrome.runtime.sendMessage({type:`pair`,server:t,code:n,name:navigator.userAgent.includes(`Edg`)?`Edge 浏览器`:`Chrome 浏览器`});i?.ok?(r.className=`msg ok`,r.textContent=`✓ 配对成功，首次同步已开始`):(r.className=`msg err`,r.textContent=`配对失败: `+(i?.error||`未知错误`))},e(`resyncBtn`).onclick=async()=>{let t=e(`pairMsg`);await chrome.runtime.sendMessage({type:`resync`}),t.className=`msg ok`,t.textContent=`✓ 已触发全量同步`};async function t(){try{let e=await chrome.runtime.sendMessage({type:`conflictStatus`});if(e?.hasConflict){let t=document.getElementById(`conflictCard`);t.style.display=`block`;let n=e.groups.reduce((e,t)=>e+t.count,0);document.getElementById(`conflictDesc`).textContent=`发现 ${e.groups.length} 组完全相同的书签（共 ${n} 条）。`,document.getElementById(`openSyncSettings`).addEventListener(`click`,async()=>{await chrome.runtime.sendMessage({type:`openSyncSettings`})})}}catch{}}t();